import{c as a,Q as t,j as s,m as o}from"./chunks/framework.rWdQudnF.js";const m=JSON.parse('{"title":"网络构建和设计方法","description":"","frontmatter":{"title":"网络构建和设计方法"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/通信系统架构设计理论与实践（第二版）/网络构建和设计方法.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/通信系统架构设计理论与实践（第二版）/网络构建和设计方法.md","lastUpdated":null}'),i={name:"架构师 在线刷题/51CT0题库 章节练习/通信系统架构设计理论与实践（第二版）/网络构建和设计方法.md"};function n(r,l,e,c,u,d){return t(),s("div",null,[...l[0]||(l[0]=[o('<h1 id="网络构建和设计方法" tabindex="-1">网络构建和设计方法 <a class="header-anchor" href="#网络构建和设计方法" aria-label="Permalink to &quot;网络构建和设计方法&quot;">​</a></h1><blockquote><p>共 6 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-在进行网络系统设计时-网络需求分析阶段需要从多个维度进行全面分析。根据系统架构设计师知识体系-网络需求分析主要包括-。" tabindex="-1">Q1. 在进行网络系统设计时，网络需求分析阶段需要从多个维度进行全面分析。根据系统架构设计师知识体系，网络需求分析主要包括（）。 <a class="header-anchor" href="#q1-在进行网络系统设计时-网络需求分析阶段需要从多个维度进行全面分析。根据系统架构设计师知识体系-网络需求分析主要包括-。" aria-label="Permalink to &quot;Q1. 在进行网络系统设计时，网络需求分析阶段需要从多个维度进行全面分析。根据系统架构设计师知识体系，网络需求分析主要包括（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 业务需求、用户需求、应用需求、计算机平台需求和网络需求</li><li><strong>B.</strong> 功能需求、性能需求、安全需求、可靠性需求和成本需求</li><li><strong>C.</strong> 硬件需求、软件需求、网络需求、存储需求和备份需求</li><li><strong>D.</strong> 接入层需求、汇聚层需求、核心层需求、广域网需求和安全需求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>A</strong></p></div></details><h2 id="q2-在网络安全控制技术中-以下哪项技术利用公共网络建立私有专用网络-具有成本低、接入方便、可扩展性强等优点-。" tabindex="-1">Q2. 在网络安全控制技术中，以下哪项技术利用公共网络建立私有专用网络，具有成本低、接入方便、可扩展性强等优点（ ）。 <a class="header-anchor" href="#q2-在网络安全控制技术中-以下哪项技术利用公共网络建立私有专用网络-具有成本低、接入方便、可扩展性强等优点-。" aria-label="Permalink to &quot;Q2. 在网络安全控制技术中，以下哪项技术利用公共网络建立私有专用网络，具有成本低、接入方便、可扩展性强等优点（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 防火墙</li><li><strong>B.</strong> 虚拟专用网络</li><li><strong>C.</strong> 访问控制</li><li><strong>D.</strong> 网络安全隔离</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q3-在进行网络需求分析时-以下哪项不属于主要考虑的需求类型-。" tabindex="-1">Q3. 在进行网络需求分析时，以下哪项不属于主要考虑的需求类型（ ）。 <a class="header-anchor" href="#q3-在进行网络需求分析时-以下哪项不属于主要考虑的需求类型-。" aria-label="Permalink to &quot;Q3. 在进行网络需求分析时，以下哪项不属于主要考虑的需求类型（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 业务需求</li><li><strong>B.</strong> 用户需求</li><li><strong>C.</strong> 硬件供应商需求</li><li><strong>D.</strong> 网络需求</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q4-在层次化网络设计中-通常采用的三层模型从下至上依次是-。" tabindex="-1">Q4. 在层次化网络设计中，通常采用的三层模型从下至上依次是（ ）。 <a class="header-anchor" href="#q4-在层次化网络设计中-通常采用的三层模型从下至上依次是-。" aria-label="Permalink to &quot;Q4. 在层次化网络设计中，通常采用的三层模型从下至上依次是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 核心层、汇聚层、接入层</li><li><strong>B.</strong> 接入层、汇聚层、核心层</li><li><strong>C.</strong> 汇聚层、接入层、核心层</li><li><strong>D.</strong> 接入层、核心层、汇聚层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q5-试题四-论网络安全体系设计-随着社会信息化的普及-计算机网络已经在各行各业得到了广泛的应用。目前-绝大多数业务处理几乎完全依赖计算机和网络执行-各种重要数据如政府文件、工资档案、财务账目和人事档案等均依赖计算机和网络进行存储与传输。另一方面-针对计算机和网络的攻击活动日益猖獗-网络安全已经成为当前社会的主要安全问题之一。-在上述背景下-国家标准《信息处理系统工程开放系统互联基本参考模型——第二部分-安全体系结构》-gb-t-9387-2-1995-定义了基于osi参考模型7层协议之上的信息安全体系-其核心内容是-为了保证异构计算机进程与进程之间远距离交换信息的安全-定义了认证服务、访问控制服务、数据机密性服务、数据完整性服务和抗抵赖性服务等5大类安全服务-以及提供这些服务的8类安全机制及相应的osi安全管理-并根据具体系统适当配置于osi模型的7层协议之中。-请围绕-网络安全体系设计-论题-依次从以下三个方面进行论述。-1-概要叙述你参与管理和开发的软件项目以及你在其中承担的主要工作-并详细阐述该软件系统在网络安全方面的要求。-2-请对gb-t-9387-2-1995中定义的5大类安全服务进行描述-阐述每类安全服务的定义和主要实现手段。-3-请结合项目实际-具体阐述你在项目中实现了上述5大类安全服务中的哪些服务-具体运用了哪些实现手段。" tabindex="-1">Q5. 试题四 论网络安全体系设计 随着社会信息化的普及，计算机网络已经在各行各业得到了广泛的应用。目前，绝大多数业务处理几乎完全依赖计算机和网络执行，各种重要数据如政府文件、工资档案、财务账目和人事档案等均依赖计算机和网络进行存储与传输。另一方面，针对计算机和网络的攻击活动日益猖獗，网络安全已经成为当前社会的主要安全问题之一。 在上述背景下，国家标准《信息处理系统工程开放系统互联基本参考模型——第二部分：安全体系结构》(GB/T 9387.2-1995)定义了基于OSI参考模型7层协议之上的信息安全体系，其核心内容是：为了保证异构计算机进程与进程之间远距离交换信息的安全，定义了认证服务、访问控制服务、数据机密性服务、数据完整性服务和抗抵赖性服务等5大类安全服务，以及提供这些服务的8类安全机制及相应的OSI安全管理，并根据具体系统适当配置于OSI模型的7层协议之中。 请围绕“网络安全体系设计”论题，依次从以下三个方面进行论述。 1．概要叙述你参与管理和开发的软件项目以及你在其中承担的主要工作，并详细阐述该软件系统在网络安全方面的要求。 2．请对GB/T 9387.2-1995中定义的5大类安全服务进行描述，阐述每类安全服务的定义和主要实现手段。 3．请结合项目实际，具体阐述你在项目中实现了上述5大类安全服务中的哪些服务，具体运用了哪些实现手段。 <a class="header-anchor" href="#q5-试题四-论网络安全体系设计-随着社会信息化的普及-计算机网络已经在各行各业得到了广泛的应用。目前-绝大多数业务处理几乎完全依赖计算机和网络执行-各种重要数据如政府文件、工资档案、财务账目和人事档案等均依赖计算机和网络进行存储与传输。另一方面-针对计算机和网络的攻击活动日益猖獗-网络安全已经成为当前社会的主要安全问题之一。-在上述背景下-国家标准《信息处理系统工程开放系统互联基本参考模型——第二部分-安全体系结构》-gb-t-9387-2-1995-定义了基于osi参考模型7层协议之上的信息安全体系-其核心内容是-为了保证异构计算机进程与进程之间远距离交换信息的安全-定义了认证服务、访问控制服务、数据机密性服务、数据完整性服务和抗抵赖性服务等5大类安全服务-以及提供这些服务的8类安全机制及相应的osi安全管理-并根据具体系统适当配置于osi模型的7层协议之中。-请围绕-网络安全体系设计-论题-依次从以下三个方面进行论述。-1-概要叙述你参与管理和开发的软件项目以及你在其中承担的主要工作-并详细阐述该软件系统在网络安全方面的要求。-2-请对gb-t-9387-2-1995中定义的5大类安全服务进行描述-阐述每类安全服务的定义和主要实现手段。-3-请结合项目实际-具体阐述你在项目中实现了上述5大类安全服务中的哪些服务-具体运用了哪些实现手段。" aria-label="Permalink to &quot;Q5. 试题四 论网络安全体系设计 随着社会信息化的普及，计算机网络已经在各行各业得到了广泛的应用。目前，绝大多数业务处理几乎完全依赖计算机和网络执行，各种重要数据如政府文件、工资档案、财务账目和人事档案等均依赖计算机和网络进行存储与传输。另一方面，针对计算机和网络的攻击活动日益猖獗，网络安全已经成为当前社会的主要安全问题之一。 在上述背景下，国家标准《信息处理系统工程开放系统互联基本参考模型——第二部分：安全体系结构》(GB/T 9387.2-1995)定义了基于OSI参考模型7层协议之上的信息安全体系，其核心内容是：为了保证异构计算机进程与进程之间远距离交换信息的安全，定义了认证服务、访问控制服务、数据机密性服务、数据完整性服务和抗抵赖性服务等5大类安全服务，以及提供这些服务的8类安全机制及相应的OSI安全管理，并根据具体系统适当配置于OSI模型的7层协议之中。 请围绕“网络安全体系设计”论题，依次从以下三个方面进行论述。 1．概要叙述你参与管理和开发的软件项目以及你在其中承担的主要工作，并详细阐述该软件系统在网络安全方面的要求。 2．请对GB/T 9387.2-1995中定义的5大类安全服务进行描述，阐述每类安全服务的定义和主要实现手段。 3．请结合项目实际，具体阐述你在项目中实现了上述5大类安全服务中的哪些服务，具体运用了哪些实现手段。&quot;">​</a></h2><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong><p>见解析</p></strong></p></div></details><h2 id="q6-【问题3】-9分-为保证各分支机构可靠、高效地向数据中心汇总业务数据-避免单点故障-对该企业总部数据中心架构设计时-应该采用哪些相关的技术" tabindex="-1">Q6. 【问题3】（9分）为保证各分支机构可靠、高效地向数据中心汇总业务数据，避免单点故障，对该企业总部数据中心架构设计时，应该采用哪些相关的技术? <a class="header-anchor" href="#q6-【问题3】-9分-为保证各分支机构可靠、高效地向数据中心汇总业务数据-避免单点故障-对该企业总部数据中心架构设计时-应该采用哪些相关的技术" aria-label="Permalink to &quot;Q6. 【问题3】（9分）为保证各分支机构可靠、高效地向数据中心汇总业务数据，避免单点故障，对该企业总部数据中心架构设计时，应该采用哪些相关的技术?&quot;">​</a></h2><details class="callout callout-info"><summary class="callout-title"><span class="callout-icon">ℹ️</span>材料</summary><div class="callout-body"><p>试题一（24分）阅读以下关于软件体系结构方面的叙述，根据要求回答下面问题。 [说明] 某大中型企业在全国各城市共有15个左右的分支机构，这些机构已经建设了相关的关系型数据库管理系统，每天负责独立地处理本区域内的业务并实时存储业务数据。PH软件公司承接了该大中型企业信息管理系统的升级改造开发任务。该软件公司的领域专家对需求进行深入分析后，得到的部分系统需求如下。 1、开发一个网络财务程序，使各地员工能在Internet上通过VPN技术进行财务单据报销和处理。 2、为了加强管理，实现对下属分支机构业务数据的异地存储备份，保证数据的安全及恢复，同时对全国业务数据进行挖掘分析，拟在该企业总部建设数据中心。 3、PH公司在设计该财务程序的体系结构时，开发项目组产生了以下分歧： 架构师许工认为应该采用客户机/服务器(C/S)架构风格，各分支机构财务部要安装一个软件客户端，通过这个客户端连接到总公司财务部主机。如果员工在外地出差，需要报销账务的，也需要安装这个客户端才能进行。 架构师郭工认为应该采用浏览器/服务器(B/S)架构风格，各分支机构及出差员工直接通过Windows操作系统自带的IE浏览器就可以连接到总公司的财务部主机。在架构评估会议上，专家对这两种方案进行综合评价，最终采用了C/S和B/S相结合的混合架构风格。</p></div></details><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>包含但不限于以下内容：①采用双链路连接Internet的备份方式。 ②对数据中心的数据库服务器采用双机冗余热备方式(或多机集群Cluster和数据库并行处理技术等)。 ③对存储设备采用RAID10级别(或全冗余的SAN结构，或全冗余的存储结构)等。</p></div></details>',19)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
